<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Checkout | Sammy Tech</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/css/style.css"></head><body><header class="topbar wrap"><a class="brand" href="index.php"><span>ST</span> SAMMY TECH</a><a class="text-link" href="cart.php">&larr; Return to cart</a></header><main class="wrap simple-page checkout"><p class="eyebrow">Secure order request</p><h1>Checkout</h1><?php if($error):?><p class="flash error"><?=e($error)?></p><?php endif;?><div class="cart-layout"><form class="order-form" action="actions/checkout_v3.php" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><h2>Contact &amp; delivery</h2><div class="form-row"><label>Full name<input name="customer_name" maxlength="150" required></label><label>Phone number<input name="phone" maxlength="25" required placeholder="0921..."></label></div><div class="form-row"><label>Email (optional)<input type="email" name="email" maxlength="150"></label><label>Alternative phone (optional)<input name="alternative_phone" maxlength="25"></label></div><label>Fulfilment<select name="delivery_method"><option value="pickup">Juba pickup - no delivery charge</option><option value="delivery">Delivery request - quote confirmed by staff</option></select></label><div class="form-row"><label>Delivery area<input name="delivery_area" maxlength="100" placeholder="e.g. Munuki"></label><label>Landmark / address<input name="delivery_address" maxlength="255" placeholder="Nearest landmark"></label></div><h2>Payment</h2><label>Payment method<select name="payment_method"><option value="cash">Cash on pickup / delivery</option><option value="mobile_money">Mobile money</option><option value="bank_transfer">Bank transfer</option></select></label><label>Pay in<select name="payment_currency"><option value="USD">US Dollars (USD) - <?=e(money($total))?></option><option value="SSP">South Sudanese Pounds (SSP) - approx. SSP <?=e(number_format($total * SSP_PER_USD, 0))?></option></select></label><p class="helper">SSP payment is calculated at 1 USD = <?=e(number_format(SSP_PER_USD, 2))?> SSP. Sammy Tech will confirm the final amount before processing.</p><div class="form-row"><label>Transaction / reference no. (optional)<input name="reference_number" maxlength="100"></label><label>Proof of payment (optional)<input type="file" name="proof" accept="image/jpeg,image/png,image/webp,application/pdf"></label></div><label>Order notes<textarea name="notes" maxlength="1000" rows="3" placeholder="Tell us anything that helps with your order."></textarea></label><button class="button button-dark" type="submit">Place order request &rarr;</button></form><aside class="cart-summary"><p class="eyebrow">Items to order</p><?php foreach($items as $item):?><p><b><?=e($item['quantity'])?> &times; <?=e($item['name'])?></b><span><?=money((float)$item['price']*$item['quantity'])?></span></p><?php endforeach;?><hr><h2><?=money($total)?></h2><p>Choose USD or the estimated SSP equivalent as your payment currency. Delivery is quoted separately by staff.</p></aside></div></main></body></html>
